# changes/156-password-lock.py - password screen for the app and the AI pages, and the league data (espn-data.js) is only published scrambled (espn-data.enc.js)
# How it works: the sync locks the data with a public key (no secret needed on GitHub); the app holds the matching private key, itself locked with the app password.
# The plain espn-data.js stays on GitHub's computer during the sync (other scripts read it) but is no longer committed (.gitignore).

GM_LOCK = '"""gm_lock.py - change 156: writes a scrambled copy of the league data (espn-data.enc.js) that only the app password can open.\n\nNo secret is needed here: the data is locked with a public key, and only the app (after the password) holds the matching private key.\nScheme: zlib, then ChaCha20 (RFC 8439) with a fresh random key; that key is sealed with RSA-OAEP (SHA-256).\n"""\nimport base64, hashlib, json, os, struct, zlib\n\nN = \nE = 65537\n\n\ndef _mgf1(seed, n):\n    out, c = b"", 0\n    while len(out) < n:\n        out += hashlib.sha256(seed + c.to_bytes(4, "big")).digest()\n        c += 1\n    return out[:n]\n\n\ndef _oaep(m):\n    k = (N.bit_length() + 7) // 8\n    h = hashlib.sha256(b"").digest()\n    db = h + b"\\x00" * (k - len(m) - 66) + b"\\x01" + m\n    seed = os.urandom(32)\n    mdb = bytes(a ^ b for a, b in zip(db, _mgf1(seed, k - 33)))\n    ms = bytes(a ^ b for a, b in zip(seed, _mgf1(mdb, 32)))\n    em = int.from_bytes(b"\\x00" + ms + mdb, "big")\n    return pow(em, E, N).to_bytes(k, "big")\n\n\ndef _rotl(v, c):\n    return ((v << c) & 0xffffffff) | (v >> (32 - c))\n\n\ndef _block(key_w, ctr, nonce_w):\n    s = [0x61707865, 0x3320646e, 0x79622d32, 0x6b206574] + key_w + [ctr] + nonce_w\n    x = s[:]\n    def qr(a, b, c, d):\n        x[a] = (x[a] + x[b]) & 0xffffffff; x[d] = _rotl(x[d] ^ x[a], 16)\n        x[c] = (x[c] + x[d]) & 0xffffffff; x[b] = _rotl(x[b] ^ x[c], 12)\n        x[a] = (x[a] + x[b]) & 0xffffffff; x[d] = _rotl(x[d] ^ x[a], 8)\n        x[c] = (x[c] + x[d]) & 0xffffffff; x[b] = _rotl(x[b] ^ x[c], 7)\n    for _ in range(10):\n        qr(0, 4, 8, 12); qr(1, 5, 9, 13); qr(2, 6, 10, 14); qr(3, 7, 11, 15)\n        qr(0, 5, 10, 15); qr(1, 6, 11, 12); qr(2, 7, 8, 13); qr(3, 4, 9, 14)\n    return struct.pack("<16I", *[(x[i] + s[i]) & 0xffffffff for i in range(16)])\n\n\ndef chacha20(key, nonce, data):\n    kw, nw = list(struct.unpack("<8I", key)), list(struct.unpack("<3I", nonce))\n    out = bytearray(len(data))\n    for i in range(0, len(data), 64):\n        ks = _block(kw, 1 + i // 64, nw)\n        ch = data[i:i + 64]\n        out[i:i + len(ch)] = bytes(a ^ b for a, b in zip(ch, ks))\n    return bytes(out)\n\n\ndef seal(text):\n    key, nonce = os.urandom(32), os.urandom(12)\n    c = chacha20(key, nonce, zlib.compress(text.encode("utf-8"), 9))\n    b = lambda x: base64.b64encode(x).decode()\n    return {"v": 1, "k": b(_oaep(key)), "n": b(nonce), "c": b(c)}\n\n\ndef write_enc(path, text, name="ESPN_ENC"):\n    tmp = path + ".tmp"\n    with open(tmp, "w", encoding="utf-8") as f:\n        f.write("window." + name + " = " + json.dumps(seal(text)) + ";\\n")\n    os.replace(tmp, path)\n'

GX_LOCK = '/* gx-lock.js - change 156: password screen, and unscrambles the league data (espn-data.enc.js) for the app and the AI pages */\n(function () {\n  if (window.gxLoadData156) return;\n  var W = { salt: "B5CJQJEcG4zzWrMfWN1XmQ==", iv: "YxLGc5MTv8hSWBLo", wk: "", it: 310000 };\n  var LS = "gx-lock156";\n  function b64(s) { var b = atob(s), u = new Uint8Array(b.length); for (var i = 0; i < b.length; i++) u[i] = b.charCodeAt(i); return u; }\n  function imp(pk) { return crypto.subtle.importKey("pkcs8", pk, { name: "RSA-OAEP", hash: "SHA-256" }, false, ["decrypt"]); }\n  function tryPw(pw) {\n    return crypto.subtle.importKey("raw", new TextEncoder().encode(pw), "PBKDF2", false, ["deriveKey"]).then(function (base) {\n      return crypto.subtle.deriveKey({ name: "PBKDF2", salt: b64(W.salt), iterations: W.it, hash: "SHA-256" }, base, { name: "AES-GCM", length: 256 }, false, ["decrypt"]);\n    }).then(function (ak) {\n      return crypto.subtle.decrypt({ name: "AES-GCM", iv: b64(W.iv) }, ak, b64(W.wk));\n    }).then(function (buf) {\n      var pk = new Uint8Array(buf), s = "";\n      for (var i = 0; i < pk.length; i++) s += String.fromCharCode(pk[i]);\n      try { localStorage.setItem(LS, btoa(s)); } catch (e) {}\n      return imp(pk);\n    });\n  }\n  function onBody(f) { if (document.body) f(); else document.addEventListener("DOMContentLoaded", f); }\n  function show(done) {\n    onBody(function () {\n      var d = document.createElement("div");\n      d.id = "gx-lock156";\n      d.setAttribute("style", "position:fixed;inset:0;z-index:99999;background:#121212;color:#fafafa;display:flex;align-items:center;justify-content:center;padding:24px;font-family:Inter,system-ui,-apple-system,sans-serif");\n      d.innerHTML = \'<form style="width:100%;max-width:320px;text-align:center"><img src="icon.png" alt="" style="width:56px;height:56px;border-radius:12px;margin:0 auto 14px;display:block"><div style="font-size:20px;font-weight:600;margin-bottom:6px">Fantasy Islands GM</div><div style="font-size:14px;color:#8f8f8f;margin-bottom:18px">Enter the password to open the app.</div><input type="password" autocomplete="current-password" placeholder="Password" style="width:100%;box-sizing:border-box;padding:12px 14px;border-radius:10px;border:1px solid #363636;background:#1a1a1a;color:#fafafa;font-size:16px;outline:none"><button type="submit" style="width:100%;margin-top:12px;padding:12px;border-radius:10px;border:0;background:#8b7cff;color:#fff;font-size:16px;font-weight:600">Unlock</button><div class="er" style="min-height:20px;margin-top:10px;font-size:14px;color:#f06a6a"></div></form>\';\n      document.body.appendChild(d);\n      var f = d.querySelector("form"), inp = d.querySelector("input"), er = d.querySelector(".er"), bt = d.querySelector("button");\n      setTimeout(function () { try { inp.focus(); } catch (e) {} }, 50);\n      f.addEventListener("submit", function (ev) {\n        ev.preventDefault();\n        er.textContent = ""; bt.disabled = true; bt.textContent = "Checking...";\n        tryPw(inp.value.trim()).then(function (k) { d.remove(); done(k); }, function () { bt.disabled = false; bt.textContent = "Unlock"; er.textContent = "Wrong password. Try again."; inp.select(); });\n      });\n    });\n  }\n  var unlocked = new Promise(function (res) {\n    var s = null;\n    try { s = localStorage.getItem(LS); } catch (e) {}\n    if (!s) { show(res); return; }\n    imp(b64(s)).then(res, function () { try { localStorage.removeItem(LS); } catch (e) {} show(res); });\n  });\n  function chacha(key, nonce, data) {\n    var kv = new DataView(key.buffer, key.byteOffset, 32), nv = new DataView(nonce.buffer, nonce.byteOffset, 12);\n    var st = new Uint32Array(16), x = new Uint32Array(16), ks = new Uint8Array(64), kd = new DataView(ks.buffer), out = new Uint8Array(data.length);\n    st[0] = 0x61707865; st[1] = 0x3320646e; st[2] = 0x79622d32; st[3] = 0x6b206574;\n    for (var i = 0; i < 8; i++) st[4 + i] = kv.getUint32(i * 4, true);\n    for (i = 0; i < 3; i++) st[13 + i] = nv.getUint32(i * 4, true);\n    function q(a, b, c, d) {\n      x[a] += x[b]; x[d] ^= x[a]; x[d] = (x[d] << 16) | (x[d] >>> 16);\n      x[c] += x[d]; x[b] ^= x[c]; x[b] = (x[b] << 12) | (x[b] >>> 20);\n      x[a] += x[b]; x[d] ^= x[a]; x[d] = (x[d] << 8) | (x[d] >>> 24);\n      x[c] += x[d]; x[b] ^= x[c]; x[b] = (x[b] << 7) | (x[b] >>> 25);\n    }\n    for (var pos = 0, ctr = 1; pos < data.length; pos += 64, ctr++) {\n      st[12] = ctr; x.set(st);\n      for (var r = 0; r < 10; r++) { q(0, 4, 8, 12); q(1, 5, 9, 13); q(2, 6, 10, 14); q(3, 7, 11, 15); q(0, 5, 10, 15); q(1, 6, 11, 12); q(2, 7, 8, 13); q(3, 4, 9, 14); }\n      for (i = 0; i < 16; i++) kd.setUint32(i * 4, (x[i] + st[i]) >>> 0, true);\n      for (var j = 0; j < 64 && pos + j < data.length; j++) out[pos + j] = data[pos + j] ^ ks[j];\n    }\n    return out;\n  }\n  function dec(E) {\n    return unlocked.then(function (k) {\n      return crypto.subtle.decrypt({ name: "RSA-OAEP" }, k, b64(E.k));\n    }).then(function (raw) {\n      var z = chacha(new Uint8Array(raw), b64(E.n), b64(E.c));\n      return new Response(new Blob([z]).stream().pipeThrough(new DecompressionStream("deflate"))).text();\n    }).then(function (t) { return JSON.parse(t); });\n  }\n  function load(src) {\n    return new Promise(function (res, rej) {\n      var s = document.createElement("script");\n      s.src = src;\n      s.onload = function () { s.remove(); res(); };\n      s.onerror = function () { s.remove(); rej(new Error("could not load " + src)); };\n      (document.head || document.documentElement).appendChild(s);\n    });\n  }\n  window.gxUnlocked156 = unlocked;\n  window.gxLoadData156 = function () {\n    return unlocked.then(function () {\n      window.ESPN_ENC = null;\n      return load("espn-data.enc.js?t=" + Date.now()).then(function () {\n        if (!window.ESPN_ENC) throw new Error("no data");\n        return dec(window.ESPN_ENC);\n      });\n    }).then(function (d) { window.ESPN_DATA = d; return d; });\n  };\n  window.gxLock156 = function () { try { localStorage.removeItem(LS); } catch (e) {} location.reload(); };\n  var me = document.currentScript;\n  if (me && me.getAttribute("data-boot")) {\n    window.ESPN_DATA = null;\n    window.gxLoadData156().catch(function (e) { console.warn("league data:", e); }).then(function () {\n      window.__gxReady156 = true;\n      if (window.__gxBoot156) window.__gxBoot156();\n    });\n  }\n})();\n'

new_file("gm_lock.py", GM_LOCK)
new_file("gx-lock.js", GX_LOCK)


def app(t):
    t = lit(t, "156: lock first",
            """<script>window.ESPN_DATA = null; document.write('<script src="espn-data.js?t=' + Date.now() + '"><\\/script>');</script>""",
            """<script>window.ESPN_DATA = null; document.write('<script data-boot="1" src="gx-lock.js?t=' + Date.now() + '"><\\/script>');</script>""",
            'data-boot="1" src="gx-lock.js')
    t = lit(t, "156: start after unlock (open)",
            "/* change 074 (gx074-loader): use the copy built on GitHub when it matches this page; otherwise translate in the browser like before */\n(function () {\n  var started = false;",
            "/* change 074 (gx074-loader): use the copy built on GitHub when it matches this page; otherwise translate in the browser like before */\nwindow.__gxBoot156 = function () { /* gx156: runs once the password is in and the data is unscrambled */\n  var started = false;",
            "window.__gxBoot156 = function () {")
    t = lit(t, "156: start after unlock (close)",
            "  } catch (e) { slow(); }\n})();\n</script>\n</body>",
            "  } catch (e) { slow(); }\n};\nif (window.__gxReady156 || !window.gxLoadData156) window.__gxBoot156();\n</script>\n</body>",
            "if (window.__gxReady156 || !window.gxLoadData156) window.__gxBoot156();")
    t = lit(t, "156: refresh reads the locked file (1)",
            '      const sc = document.createElement("script");\n      sc.src = "espn-data.js?t=" + Date.now();\n      sc.onload = () => {',
            '      const sc = { remove() {} }; /* gx156: the data comes unscrambled from gx-lock.js */\n      const onl156 = () => {',
            "const onl156 = () => {")
    t = lit(t, "156: refresh reads the locked file (2)",
            '      sc.onerror = () => sc.remove();\n      document.head.appendChild(sc);\n      const ls = document.createElement("script"); ls.src = "lines-data.js',
            '      if (window.gxLoadData156) window.gxLoadData156().then(onl156, () => {});\n      const ls = document.createElement("script"); ls.src = "lines-data.js',
            "window.gxLoadData156().then(onl156, () => {});")
    return t


def ai_page(t):
    t = lit(t, "156: lock on AI page", "</head>", '<script src="gx-lock.js"></script>\n</head>', '<script src="gx-lock.js"></script>')
    t = lit(t, "156: AI page data", 'await loadScript("espn-data.js");', "await window.gxLoadData156().catch(() => null); /* gx156 */", "gxLoadData156().catch(() => null); /* gx156 */")
    return t


def sync(t):
    return lit(t, "156: scrambled copy",
               '    f.write("window.ESPN_DATA = " + json.dumps(data) + ";\\n")\n',
               '    f.write("window.ESPN_DATA = " + json.dumps(data) + ";\\n")\n'
               'try:  # change 156: the published copy is scrambled; only the app password opens it\n'
               '    import gm_lock\n'
               '    gm_lock.write_enc(os.path.join(HERE, "espn-data.enc.js"), json.dumps(data))\n'
               'except Exception as ex:\n'
               '    print(f"(lock) could not write espn-data.enc.js: {ex}")\n',
               "change 156: the published copy is scrambled")


def ignore(t):
    return t if "espn-data.js" in t.split() else t.rstrip("\n") + "\nespn-data.js\n"


edit(APP, app)
edit("ai-dashboard.html", ai_page)
edit("ai-history.html", ai_page)
edit("espn_sync.py", sync)
